    <script src="https://cdnjs.cloudflare.com/ajax/libs/qrcodejs/1.0.0/qrcode.min.js"></script> {{-- Script QRCode.js --}}

    <script>
        window.addEventListener('DOMContentLoaded', function () {
            const qrText = "{{ route('cert.detail', ['id' => $sesi->id, 'name' => rawurlencode($sesi->name)]) }}";
            const tempDiv = document.getElementById('qr-temp');
            tempDiv.innerHTML = '';

            const qr = new QRCode(tempDiv, {
                text: qrText,
                width: 85,
                height: 85
            });

            setTimeout(() => {
                const img = tempDiv.querySelector('img');
                if (img) {
                    const dataURL = img.src;
                    const svg = document.getElementById('Layer_1');

                    const qrImage = document.createElementNS("http://www.w3.org/2000/svg", "image");
                    qrImage.setAttributeNS(null, 'href', dataURL);

                    const svgWidth = 800; // Sesuaikan dengan lebar SVG kamu
                    const qrWidth = 90;
                    const marginRight = 30;
                    const xPos = svgWidth - qrWidth - marginRight;

                    qrImage.setAttributeNS(null, 'x', xPos.toString());
                    qrImage.setAttributeNS(null, 'y', '390');
                    qrImage.setAttributeNS(null, 'width', qrWidth.toString());
                    qrImage.setAttributeNS(null, 'height', qrWidth.toString());

                    svg.appendChild(qrImage);
                }
            }, 300);
        });
    </script>

    <script src="https://cdn.jsdelivr.net/npm/canvg@3.0.7/lib/umd.min.js"></script>
    <script src="https://cdnjs.cloudflare.com/ajax/libs/jspdf/2.5.1/jspdf.umd.min.js"></script>

    <script>
        function printSVG() {
            const svg = document.getElementById('Layer_1');
            const svgData = new XMLSerializer().serializeToString(svg);
            const printWindow = window.open('', '', 'height=800,width=1245');
            printWindow.document.write('<html><head><title>Print Sertifikat</title></head><body>');
            printWindow.document.write('<div style="text-align:center;">' + svgData + '</div>');
            printWindow.document.write('</body></html>');
            printWindow.document.close();
            printWindow.focus();
            printWindow.print();
        }
