        function downloadSVG() {
            const svg = document.getElementById('Layer_1');
            const svgData = new XMLSerializer().serializeToString(svg);
            const blob = new Blob([svgData], { type: 'image/svg+xml;charset=utf-8' });
            const url = URL.createObjectURL(blob);

            // Misalnya mau pakai nama peserta dari Blade
            const fileName = "{{ $sesi->name ?? 'sertifikat' }}";
            const safeName = fileName.replace(/[^a-z0-9_\- ]/gi, '_').toLowerCase();

            const link = document.createElement("a");
            link.href = url;
            link.download = `sertifikat_${safeName}.svg`;
            document.body.appendChild(link);
            link.click();
            document.body.removeChild(link);
        }

    </script>

    <script>
        async function downloadPDF() {
            const svgElement = document.getElementById('Layer_1');
            const button = document.getElementById('downloadBtn');
            const fileName = button.getAttribute('data-name') || "sertifikat";

            const svgData = new XMLSerializer().serializeToString(svgElement);
            const canvas = document.createElement('canvas');
            const scaleFactor = 2;
            canvas.width = 1245 * scaleFactor;
            canvas.height = 800 * scaleFactor;

            const ctx = canvas.getContext('2d');
            const v = await canvg.Canvg.from(ctx, svgData);
            await v.render();

            const imgData = canvas.toDataURL('image/png');
            const { jsPDF } = window.jspdf;
            const pdf = new jsPDF({
                orientation: 'landscape',
                unit: 'px',
                format: [canvas.width, canvas.height]
            });

            pdf.addImage(imgData, 'PNG', 0, 0, canvas.width, canvas.height);

            // Format nama file (hapus karakter tidak valid di nama file)
            const safeName = fileName.replace(/[^a-z0-9_\- ]/gi, '_');
            pdf.save(`Sertifikat_${safeName}.pdf`);
        }
    </script>
